const item = $input.first().json;
const ALLOWED = ['1342891001', '5765665250', '5930338959'];
const cb = item.callback_query;
const msg = item.message;
const incomingChatId = String(cb?.message?.chat?.id ?? msg?.chat?.id ?? '');
if (!ALLOWED.includes(incomingChatId)) {
  return [{ json: { route: 'unknown', sessionId: '', chatId: incomingChatId, callbackQueryId: '', messageId: 0, fileId: '' } }];
}
if (cb) {
  const parts = (cb.data || '').split(':');
  const route = (parts[0] || '') + ':' + (parts[1] || '');
  const sessionId = parts[2] || '';
  return [{ json: { route, sessionId, chatId: String(cb.message?.chat?.id ?? ''), callbackQueryId: cb.id, messageId: cb.message?.message_id ?? 0, fileId: '' } }];
}
if (msg && Array.isArray(msg.photo) && msg.photo.length) {
  const largest = msg.photo[msg.photo.length - 1];
  return [{ json: { route: 'msg:photo', sessionId: '', chatId: String(msg.chat?.id ?? ''), callbackQueryId: '', messageId: 0, fileId: largest.file_id } }];
}
if (msg && msg.text && msg.text.toLowerCase().trim() === 'post') {
  return [{ json: { route: 'msg:post', sessionId: '', chatId: String(msg.chat?.id ?? ''), callbackQueryId: '', messageId: 0, fileId: '' } }];
}
return [{ json: { route: 'unknown', sessionId: '', chatId: String(msg?.chat?.id ?? ''), callbackQueryId: '', messageId: 0, fileId: '' } }];

const pr = $('Parse Reply').item.json;
const ackMap = {'q1:y':'✅ Posting today!','q1:n':'❌ Skipping today.','q2:pic':'🖼 Picture post selected.','q2:vid':'🎬 Video post selected.','q2b:own':'📷 Upload your own photo.','q2b:gen':'✨ Generating an image.','q3:ok':'✅ Approved!','q3:rg':'🔁 Regenerating...','q3:cx':'❌ Cancelled.','q3:rv':'🔁 Regenerating video...'};
return [{ json: { ...pr, ackText: ackMap[pr.route] || '✓' } }];

let arr;
const first = $input.first().json;
if (Array.isArray(first)) {
  arr = first.filter(i => typeof i.src === "string" && i.src.startsWith("http"));
} else {
  arr = $input.all().map(i => i.json).filter(i => typeof i.src === "string" && i.src.startsWith("http"));
}
if (!arr.length) throw new Error("Gallery API returned no images");
const idx = Math.floor(Math.random() * arr.length);
const picked = arr[idx];
const postRow = $("Fetch Post Row").first().json;
return [{ json: { ...postRow, galleryImageUrl: picked.src, galleryImageAlt: picked.alt } }];

const theme = $input.first().json.theme || 'Food spotlight';
const galleryImageUrl = $input.first().json.galleryImageUrl;

const themeText = {
  'Food spotlight': 'Overlay elegant gold text into the scene — something like "Pub Food Done Right" or "Fresh from Our Kitchen". Text only — do not add any food or objects.',
  'Atmosphere / weekend vibe': 'Overlay elegant gold text into the scene — something like "Your Weekend Starts Here" or "Weekends at The Miners Arms". Text only.',
  'Bar & drinks': 'Overlay elegant gold text into the scene — something like "Ales, Spirits & Cocktails" or "Pull up a Stool". Text only — do not add any drinks or objects.',
  'Community / local feel': 'Overlay friendly gold text into the scene — something like "Your Local, Your Place" or "Where West Brom Gathers". Text only.',
  'Three-kitchen heritage': 'Overlay elegant heritage gold typography into the scene — something like "English · Indian · Chinese" or "Three Cuisines, One Pub". Text only.',
  'Weekly special or event': 'Overlay bold promotional gold text into the scene — something like "Chef\'s Special This Week" or "Ask About Today\'s Special". Text only.'
};

const textInstruction = themeText[theme] || themeText['Food spotlight'];

const prompt = `You are editing a real photograph from inside The Miners Arms pub in West Bromwich — a warm, upscale British pub.

