  category: 'food',
  subject_description: 'a beautifully presented pub dish on a warm wooden table',
  background_description: 'warm bokeh pub interior with amber lighting',
  lighting: 'warm candlelight with a golden overhead glow',
  motion_elements: 'gentle steam rising from the food, sauce glistening in the light',
  camera_move: 'slow cinematic push-in',
  mood: 'warm'
};
try { const m = String(raw).match(/\{[\s\S]*\}/); if (m) { parsed = Object.assign(parsed, JSON.parse(m[0])); } } catch (e) {}

const videoPrompt = [
  'Cinematic short video for The Miners Arms pub in West Bromwich.',
  'Scene: ' + parsed.subject_description + '.',
  'Background: ' + parsed.background_description + '.',
  'Lighting: ' + parsed.lighting + '.',
  'Camera: ' + parsed.camera_move + ' with subtle parallax depth.',
