  throw new Error('Gemini returned no image. Response: ' + JSON.stringify(response).slice(0, 400));
}

const ext = imageMime.includes('png') ? 'png' : 'jpg';

return [{
  json: { caption },
  binary: {
    data: {
      data: imageBase64,
      mimeType: imageMime,
      fileExtension: ext,
      fileName: 'composite.' + ext
    }
  }
}];

const foodUpload = $input.first().json?.file ?? {};
const foodFileUri = foodUpload.uri ?? '';
const foodMime = foodUpload.mimeType ?? 'image/png';
const galleryBinaryMeta = $('Prepare Composite').first().binary?.background;
const caption = $('Prepare Composite').first().json?.caption ?? '';

if (!galleryBinaryMeta) throw new Error('Gallery background binary missing from Prepare Composite');
if (!foodFileUri) throw new Error('Food file URI missing from Gemini Files upload response');

// Copies binary metadata reference only — no .data access, no base64 read
return [{
  json: { foodFileUri, foodMime, caption },
  binary: { data: galleryBinaryMeta }
}];

const galleryUpload = $input.first().json?.file ?? {};
const galleryFileUri = galleryUpload.uri ?? '';
const galleryMime = galleryUpload.mimeType ?? 'image/jpeg';

const prev = $('Restore Gallery Binary').first().json;
const foodFileUri = prev?.foodFileUri ?? '';
const foodMime = prev?.foodMime ?? 'image/png';
const caption = prev?.caption ?? '';

if (!galleryFileUri) throw new Error('Gallery file URI missing from Gemini Files upload response');
if (!foodFileUri) throw new Error('Food file URI missing');

const compositePrompt = `You are compositing a professional food promotional photo for The Miners Arms, a warm British pub in West Bromwich.

You are given two images:
- Image 1: a food dish with its background removed (transparent cutout). This is a REAL product photo of the actual dish served to customers.
- Image 2: the interior of The Miners Arms pub.

THE SINGLE MOST IMPORTANT RULE — THE DISH IS UNTOUCHABLE:
Reproduce the dish from Image 1 EXACTLY as provided. Do NOT redraw, repaint, restyle, regenerate, enhance, or "improve" it. Do not change its plating, garnish, portion size, colours, textures, proportions, or the plate/container it sits in. It must remain the identical photograph of the dish — customers must receive exactly what they see.

Your ONLY job is the scene AROUND the dish:
1. Place the unchanged dish as the sharp foreground hero, naturally sized on a table surface
2. Build the background from Image 2 — warm golden pub atmosphere with soft bokeh blur
3. Add a soft, realistic contact shadow beneath the dish matching the ambient light
4. Blend only the outer EDGES of the cutout into the scene so there are no visible cutout lines — never alter the interior of the dish
5. Square 1:1 composition, Instagram-ready
6. No text, no watermarks, no logos

The result must read as if the actual dish from Image 1 was photographed inside the pub — the dish identical, only its surroundings new.`;

const requestBody = {
  contents: [{
    parts: [
      { text: compositePrompt },
      { file_data: { mime_type: foodMime, file_uri: foodFileUri } },
      { file_data: { mime_type: galleryMime, file_uri: galleryFileUri } }
    ]
  }],
  generationConfig: {
    responseModalities: ['IMAGE', 'TEXT']
  }
};

return [{ json: { caption, requestBody } }];
